<?php
declare(strict_types=1);
require dirname(__DIR__, 2) . '/config/bootstrap.php';
require dirname(__DIR__, 2) . '/app/Auth/Auth.php';
require dirname(__DIR__, 2) . '/app/Billing/Wallet.php';
use ResellNom\Auth\Auth;
use ResellNom\Billing\Wallet;
$pdo=db(); $auth=new Auth($pdo); $admin=$auth->requireRole(['admin']); $message=null; $error=null;
try {
 if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf($_POST['csrf']??''); $action=$_POST['action']??'';
  if($action==='wallet'){
   $uid=(int)$_POST['user_id']; $amount=(float)$_POST['amount']; $type=$_POST['type']??'credit';
   if($amount<=0) throw new RuntimeException('Amount must be greater than zero.');
   $wallet=new Wallet($pdo); $new=$type==='debit'?$wallet->debit($uid,$amount,'Admin wallet adjustment',$admin['id']):$wallet->credit($uid,$amount,'Admin wallet adjustment',$admin['id']); $message='Wallet updated. New balance: '.number_format($new,2);
  } elseif($action==='promo'){
   $code=strtoupper(trim((string)$_POST['code'])); $registrarId=(int)($_POST['registrar_id']??0); $tld=trim((string)$_POST['tld']); $pa=$_POST['promo_action']; $dt=$_POST['discount_type']; $dv=(float)$_POST['discount_value'];
   if($code===''||$dv<=0) throw new RuntimeException('Enter a valid promotion.');
   $s=$pdo->prepare('INSERT INTO promotions(code,registrar_id,tld,action,discount_type,discount_value,status) VALUES(?,?,?,?,?,?,\'active\')'); $s->execute([$code,$registrarId>0?$registrarId:null,$tld!==''?strtolower(ltrim($tld,'.')):null,$pa,$dt,$dv]); $message='Promotion created: '.$code;
  } elseif($action==='tld'){
   $rid=(int)$_POST['registrar_id']; $tld=strtolower(ltrim(trim((string)$_POST['tld']),'.')); $r=(float)$_POST['register_price']; $tr=(float)$_POST['transfer_price']; $re=(float)$_POST['renewal_price'];
   if($tld===''||$r<0||$tr<0||$re<0) throw new RuntimeException('Invalid TLD pricing.');
   $s=$pdo->prepare('INSERT INTO tld_prices(registrar_id,tld,register_price,transfer_price,renewal_price) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE register_price=VALUES(register_price),transfer_price=VALUES(transfer_price),renewal_price=VALUES(renewal_price)'); $s->execute([$rid,$tld,$r,$tr,$re]); $message='TLD pricing saved.';
  }
 }
} catch(Throwable $e){$error=$e->getMessage();}
$users=$pdo->query("SELECT id,name,email,role,balance FROM users WHERE role<>'admin' ORDER BY id DESC LIMIT 100")->fetchAll();
$registrars=$pdo->query("SELECT id,name,status,priority FROM registrars ORDER BY priority,id")->fetchAll();
$prices=$pdo->query("SELECT tp.tld,tp.register_price,tp.transfer_price,tp.renewal_price,r.name registrar FROM tld_prices tp JOIN registrars r ON r.id=tp.registrar_id ORDER BY tp.tld,r.priority LIMIT 100")->fetchAll();
$promos=$pdo->query("SELECT p.code,p.tld,p.action,p.discount_type,p.discount_value,p.status,p.starts_at,p.ends_at,r.name registrar FROM promotions p LEFT JOIN registrars r ON r.id=p.registrar_id ORDER BY p.id DESC LIMIT 100")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Billing Admin · ResellNom</title><style>body{font-family:system-ui;background:#f5f7fb;margin:0;color:#111827}.wrap{max-width:1200px;margin:30px auto;padding:20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:18px}.card{background:#fff;padding:20px;border-radius:14px;box-shadow:0 4px 18px #0001;margin-bottom:18px}input,select{width:100%;box-sizing:border-box;padding:10px;margin:5px 0 12px;border:1px solid #ddd;border-radius:8px}button{padding:10px 14px;background:#111827;color:#fff;border:0;border-radius:8px;font-weight:700}.ok{background:#dcfce7;padding:10px;border-radius:8px}.err{background:#fee2e2;padding:10px;border-radius:8px}table{width:100%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #eee;text-align:left}</style></head><body><main class="wrap"><h1>Billing & Pricing</h1><?php if($message):?><div class="ok"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="err"><?=htmlspecialchars($error)?></div><?php endif;?><div class="grid"><section class="card"><h2>Wallet</h2><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="wallet"><select name="user_id" required><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=htmlspecialchars($u['name'])?> · <?=htmlspecialchars($u['role'])?> · <?=number_format((float)$u['balance'],2)?></option><?php endforeach;?></select><select name="type"><option value="credit">Credit</option><option value="debit">Debit</option></select><input type="number" step="0.00000001" min="0.00000001" name="amount" placeholder="Amount" required><button>Update Wallet</button></form></section><section class="card"><h2>TLD Price</h2><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="tld"><select name="registrar_id" required><?php foreach($registrars as $r):?><option value="<?=$r['id']?>"><?=htmlspecialchars($r['name'])?> (<?=$r['status']?>)</option><?php endforeach;?></select><input name="tld" placeholder="com" required><input name="register_price" type="number" step="0.00000001" min="0" placeholder="Register" required><input name="transfer_price" type="number" step="0.00000001" min="0" placeholder="Transfer" required><input name="renewal_price" type="number" step="0.00000001" min="0" placeholder="Renewal" required><button>Save TLD Price</button></form></section><section class="card"><h2>Promotion</h2><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="promo"><select name="registrar_id"><option value="0">All Companies</option><?php foreach($registrars as $r):?><option value="<?=$r['id']?>"><?=htmlspecialchars($r['name'])?> (<?=$r['status']?>)</option><?php endforeach;?></select><input name="code" placeholder="DOM50" required><input name="tld" placeholder="com (optional)"><select name="promo_action"><option>all</option><option>register</option><option>transfer</option><option>renewal</option></select><select name="discount_type"><option value="percent">Percent</option><option value="fixed">Fixed</option></select><input name="discount_value" type="number" step="0.00000001" min="0.00000001" placeholder="Discount" required><button>Create Promotion</button></form></section></div><section class="card"><h2>Current TLD Prices</h2><table><tr><th>TLD</th><th>Registrar</th><th>Register</th><th>Transfer</th><th>Renewal</th></tr><?php foreach($prices as $p):?><tr><td>.<?=htmlspecialchars($p['tld'])?></td><td><?=htmlspecialchars($p['registrar'])?></td><td><?=$p['register_price']?></td><td><?=$p['transfer_price']?></td><td><?=$p['renewal_price']?></td></tr><?php endforeach;?></table></section><section class="card"><h2>Promotions</h2><table><tr><th>Company</th><th>Code</th><th>TLD</th><th>Action</th><th>Discount</th><th>Status</th></tr><?php foreach($promos as $p):?><tr><td><?=htmlspecialchars($p['registrar']??'All Companies')?></td><td><?=htmlspecialchars($p['code'])?></td><td><?=htmlspecialchars($p['tld']??'All')?></td><td><?=htmlspecialchars($p['action'])?></td><td><?=htmlspecialchars($p['discount_value'])?> <?=htmlspecialchars($p['discount_type'])?></td><td><?=htmlspecialchars($p['status'])?></td></tr><?php endforeach;?></table></section></main></body></html>
